package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class EnabledUserEmailTemplateVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property enabled user email template of tenant config ")
  void test_enabled_user_email_template_v_o_builder() {
    Assertions.assertFalse(
        EnabledUserEmailTemplateVO.nullValue().getEnabledUserEmailTemplate().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        EnabledUserEmailTemplateVO.tryFrom(null).getEnabledUserEmailTemplate().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        EnabledUserEmailTemplateVO.from("one").getEnabledUserEmailTemplate().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> EnabledUserEmailTemplateVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", EnabledUserEmailTemplateVO.from("one").toString());
  }
}
